  /**
   * This method returns the valid address lane count for the mentioned flash
   * command opcode & flash protocol mode.
   */ 
  extern virtual function int get_spi_flash_address_lane_count(input svt_spi_types::flash_protocol_mode_enum flash_protocol_mode, svt_spi_types::flash_command_enum flash_command, int xSPI_command_list_index=0, int xSPI_command_list_protocol_mode_index=0, svt_spi_types::xSPI_profile_type_enum xSPI_profile_type=svt_spi_types::NO_PROFILE);

  //----------------------------------------------------------------------------
  /**
